#include <bits/stdc++.h>
using namespace std;

inline int read() {
    char c = getchar();
    int ret = 0;
    while (!isdigit(c)) c = getchar();
    do {
        ret = ret * 10 + c - '0';
    } while (isdigit(c = getchar()));
    return ret;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n = read();
    using nd = pair<int, int>;
    vector<nd> a(n + 5);
    for (int i = 1; i <= n; ++i) {
        a[i].first = read(), a[i].second = read();
        a[i].second -= a[i].first;
    }
    sort(a.begin() + 1, a.begin() + n + 1);
    vector<int> dp;
    for (int i = 1; i <= n; ++i) {
        if (a[i].second < 0) continue;
        if (dp.empty() || a[i].second >= dp.back()) dp.emplace_back(a[i].second);
        else {
            auto it = upper_bound(dp.begin(), dp.end(), a[i].second);
            *it = a[i].second;
        }
    }
    cout << dp.size() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
#define il inline
typedef long long ll;
const int N = 1e5 + 10;
struct node
{
	int x, t;
	friend bool operator < (const node &n1, const node &n2)
	{
		return n1.x == n2.x ? n1.t < n2.t : n1.x < n2.x;
	}
}a[N];
int f[N], n, tot;
unordered_map<int, int> mp;
set<int> s;
struct node2
{
	int v;
}ST[N << 2];
il void push_up(int ind)
{
	ST[ind].v = max(ST[ind << 1].v, ST[ind << 1 | 1].v);
}
il void upd(int ind, int l, int r, int tl, int tr, int x)
{
	if(l == r)
	{
		ST[ind].v = max(ST[ind].v, x);
		return;
	}
	int mid = (l + r) >> 1;
	if(tl <= mid) upd(ind << 1, l, mid, tl, tr, x);
	if(tr > mid) upd(ind << 1 | 1, mid + 1, r, tl, tr, x);
	push_up(ind);
}
il int ask(int ind, int l, int r, int tl, int tr)
{
	if(tl > tr) return 0;
	if(tl <= l && r <= tr) return ST[ind].v;
	int mid = (l + r) >> 1;
	if(tl <= mid && tr > mid) return max(ask(ind << 1, l, mid, tl, tr), ask(ind << 1 | 1, mid + 1, r, tl, tr));
	if(tl <= mid) return ask(ind << 1, l, mid, tl, tr);
	return ask(ind << 1 | 1, mid + 1, r, tl, tr);
}
int main()
{
	cin >> n;
	for(int i = 1;i <= n;++i) 
	{
		cin >> a[i].x >> a[i].t;
		s.insert(a[i].x - a[i].t);
	}
	sort(a + 1, a + 1 + n);
	for(auto i : s) mp[i] = ++tot;
	int ans = 0;
	for(int i = 1;i <= n;++i)
	{
		if(a[i].x > a[i].t) continue;
		f[i] = ask(1, 1, tot, mp[a[i].x - a[i].t], tot) + 1;
		ans = max(ans, f[i]);
		upd(1, 1, tot, mp[a[i].x - a[i].t], mp[a[i].x - a[i].t], f[i]);
	}
	cout << ans;
	return 0;
}
